func (h *hasher) proofHash(original node) []byte {
	switch n := original.(type) {
	case *shortNode:
		return bytes.Clone(h.encodeShortNode(n))
	case *fullNode:
		return bytes.Clone(h.encodeFullNode(n))
	default:
		panic(fmt.Errorf("unexpected node type, %T", original))
	}
